-- authors (5 rows)
INSERT INTO `authors` (`id`, `slug`, `name`, `role`, `credentials`, `bio`, `long_bio`, `avatar`, `expertise`, `years_experience`, `social`, `sort_order`) VALUES
  ('author-usman-rafiq', 'usman-rafiq', 'Usman Rafiq', 'Founder & Lead AI Instructor', 'AI Automation Consultant, ex-Product Engineer', 'Founder of Globify Tech Institute. Builds AI automation systems for businesses across Pakistan and the Gulf, and has trained more than 2,000 students in practical AI and freelancing.', '[\"Usman started Globify Tech Institute in 2019 after eight years of building software and marketing systems for clients in Pakistan, the UAE and the UK. He kept meeting talented graduates who could pass an exam but had never shipped anything, and built the institute specifically to close that gap.\",\"Today he leads the AI & Automation track and the Freelancing Mastery programme, and personally reviews the capstone project of every AI batch. His consulting work — building retrieval systems, WhatsApp agents and automation pipelines for real businesses — feeds directly back into the syllabus each term.\",\"He writes about the practical economics of AI skills in Pakistan: what actually earns, what is hype, and how someone in Faisalabad can compete for the same work as someone in London.\"]', '/images/generated/authors/usman-rafiq.webp', '[\"AI & Automation\",\"Prompt Engineering\",\"Freelancing\",\"Business Strategy\"]', 12, '{\"linkedin\":\"https://linkedin.com/in/globifytech\",\"twitter\":\"https://x.com/globifytech\",\"email\":\"usman@globifytech.com\"}', 0),
  ('author-ayesha-siddiqui', 'ayesha-siddiqui', 'Ayesha Siddiqui', 'Head of Digital Marketing', 'Google Ads & Meta Certified, Performance Marketer', 'Performance marketer managing multi-market ad budgets for e-commerce and education brands. Leads the Digital Marketing and TikTok Shop tracks at Globify.', '[\"Ayesha has spent nine years running paid acquisition for e-commerce, education and local service businesses, with campaigns across Pakistan, the UAE and the United States. She is Google Ads and Meta Blueprint certified and has managed cumulative ad spend well into the crores.\",\"At Globify she rebuilt the Digital Marketing syllabus around live budgets after concluding that no amount of screenshot-based teaching produces a marketer who can be trusted with a client account. Every student in her track runs real campaigns.\",\"She writes about search, paid social and the measurement problems that quietly waste most Pakistani marketing budgets.\"]', '/images/generated/authors/ayesha-siddiqui.webp', '[\"SEO\",\"Meta Ads\",\"Google Ads\",\"Analytics\",\"Content Strategy\"]', 9, '{\"linkedin\":\"https://linkedin.com/in/globifytech\",\"email\":\"ayesha@globifytech.com\"}', 1),
  ('author-hassan-mehmood', 'hassan-mehmood', 'Hassan Mehmood', 'Senior Software Engineering Instructor', 'Full-Stack Engineer, React & Next.js Specialist', 'Full-stack engineer and instructor. Teaches Web Development, Python and WordPress, with a focus on shipping deployed, production-grade projects.', '[\"Hassan has built production applications for fintech, logistics and e-commerce companies, working primarily in the JavaScript and Python ecosystems. He has contributed to open-source tooling and has mentored well over a thousand students through their first deployed application.\",\"His teaching philosophy is uncompromising on one point: nothing counts until it is deployed and someone else can use it. Students in his tracks push to GitHub from week two and have a live URL by the end of the first month.\",\"He writes about web development trends, performance engineering and what Pakistani development teams are actually hiring for.\"]', '/images/generated/authors/hassan-mehmood.webp', '[\"React\",\"Next.js\",\"Node.js\",\"Python\",\"Performance\",\"Databases\"]', 10, '{\"linkedin\":\"https://linkedin.com/in/globifytech\",\"github\":\"https://github.com/globifytech\",\"email\":\"hassan@globifytech.com\"}', 2),
  ('author-zainab-khan', 'zainab-khan', 'Zainab Khan', 'Head of Design', 'Brand & Product Designer, Adobe Certified', 'Brand and product designer leading the Graphic Designing, UI/UX and Video Editing tracks. Ten years of identity and product work for regional brands.', '[\"Zainab has designed brand identities, packaging and digital products for clients across Pakistan and the Middle East, including several textile and FMCG brands based in Faisalabad. She is Adobe Certified and works daily in Figma, Illustrator and After Effects.\",\"She built Globify\'s design curriculum around critique. Students present work every week and learn to defend decisions, which is the single skill that separates a designer who gets hired from one who only makes pretty files.\",\"She writes about design careers, portfolio strategy and the realities of freelance design pricing.\"]', '/images/generated/authors/zainab-khan.webp', '[\"Brand Identity\",\"UI/UX\",\"Figma\",\"Adobe Creative Suite\",\"Motion Design\"]', 10, '{\"linkedin\":\"https://linkedin.com/in/globifytech\",\"email\":\"zainab@globifytech.com\"}', 3),
  ('author-bilal-ahmed', 'bilal-ahmed', 'Bilal Ahmed', 'E-Commerce & Career Services Lead', 'Amazon Seller & VA Trainer, Career Counsellor', 'Amazon and e-commerce specialist running the Amazon VA, Shopify and Office Automation tracks, plus Globify\'s placement and career counselling cell.', '[\"Bilal has managed Amazon accounts for sellers in the US and UK since 2018 and has run his own private-label products. He knows both sides of the marketplace, which is why his students learn account management as a service rather than as theory.\",\"He also runs Globify\'s career services: CV clinics, interview preparation, employer outreach and internship placement. He personally tracks graduate outcomes each batch, which is where the institute\'s placement figures come from.\",\"He writes about e-commerce operations, the freelance job market and how to turn a certificate into an actual offer.\"]', '/images/generated/authors/bilal-ahmed.webp', '[\"Amazon FBA\",\"E-Commerce\",\"Career Counselling\",\"Excel & Reporting\"]', 8, '{\"linkedin\":\"https://linkedin.com/in/globifytech\",\"email\":\"bilal@globifytech.com\"}', 4)
