-- testimonials (12 rows)
INSERT INTO `testimonials` (`id`, `name`, `role`, `course`, `course_slug`, `city`, `avatar`, `rating`, `quote`, `story`, `outcome`, `featured`, `sort_order`) VALUES
  ('ts-1', 'Muhammad Hamza', 'Freelance Web Developer', 'Full Stack Development with AI', 'full-stack-development-with-ai', 'Faisalabad', '/images/generated/students/student-01.webp', 5, 'I joined with zero coding background after finishing my B.Com. Six months later I had four deployed projects, and my first Upwork contract came three weeks after graduation.', 'Hamza came from a commerce background with no technical exposure at all. What made the difference was the deployment discipline — every project went live with a real URL, so when a client asked \"what have you built?\", he had links instead of promises. He now works with two long-term international clients and has begun subcontracting overflow work to juniors from his own batch.', 'Earning $1,800+/month freelancing', 1, 0),
  ('ts-2', 'Ayesha Noor', 'Digital Marketing Executive', 'Digital Media Marketing with AI', 'digital-media-marketing-with-ai', 'Faisalabad', '/images/generated/students/student-02.webp', 5, 'Running live campaigns with a real budget during the course is what got me hired. In the interview I could open a dashboard and walk them through actual results.', 'Ayesha was working in a retail job when she enrolled in the evening batch. The live-budget capstone gave her a genuine case study — a Meta campaign for a local clothing brand with tracked ROAS. She was hired by a Lahore-based agency before her batch even finished and was promoted within eight months.', 'Hired at Rs 95,000/month', 1, 1),
  ('ts-3', 'Ali Raza', 'Amazon Virtual Assistant', 'TikTok Shop', 'tiktok-shop', 'Jhang', '/images/generated/students/student-03.webp', 5, 'The PPC module alone paid for the course ten times over. I now manage three US seller accounts from home and get paid in dollars every month.', 'Ali travelled from Jhang for the weekend batch. He started by offering free product research to sellers in Facebook groups to build proof, converted his second free audit into a paid retainer, and grew from there. He now manages three accounts and has started training his younger brother.', '$1,400/month in retainers', 1, 2),
  ('ts-4', 'Fatima Zahra', 'Brand Designer', 'Graphic Designing', 'graphic-designing', 'Faisalabad', '/images/generated/students/student-04.webp', 5, 'The weekly critique sessions were uncomfortable and completely necessary. I learned to explain my design decisions, and that is what clients actually pay for.', 'Fatima had been designing informally on Canva for family businesses. The identity module reframed her work entirely — she stopped making posts and started building systems. Her capstone brand identity became her first paid project when the fictional brief turned into a real client from her father\'s network.', 'Runs a 3-person design studio', 1, 3),
  ('ts-5', 'Usman Tariq', 'AI Automation Consultant', 'Full Stack Development with AI', 'full-stack-development-with-ai', 'Faisalabad', '/images/generated/students/student-05.webp', 5, 'I built a WhatsApp lead bot for a property dealer as my capstone. He asked what it would cost to keep running. That was my first monthly retainer.', 'Usman was a mobile-shop owner who wanted to understand AI before it disrupted him. He finished the course with four working automations and pivoted his business entirely — he now sells automation retainers to SMEs across Faisalabad and Sargodha.', 'Rs 220,000/month consulting', 1, 4),
  ('ts-6', 'Hira Aslam', 'UI/UX Designer', 'Graphic Designing', 'graphic-designing', 'Sargodha', '/images/generated/students/student-06.webp', 5, 'Three complete case studies, properly written up. That portfolio got me shortlisted at every company I applied to, including two remote-first ones.', 'Hira transitioned from a graphic design job where she felt stuck at Rs 45,000. The research and testing modules gave her vocabulary she had never had, and the case-study writing turned her work into arguments rather than screenshots. She accepted a remote product design role at nearly three times her previous salary.', 'Remote role, Rs 180,000/month', 1, 5),
  ('ts-7', 'Bilal Hussain', 'Short-Form Video Editor', 'Video Editing: Beginner to Pro', 'video-editing', 'Faisalabad', '/images/generated/students/student-07.webp', 5, 'I edit for two YouTube channels on monthly retainer now. The short-form module is what actually sells — every client wants clips.', NULL, '$900/month in retainers', 0, 6),
  ('ts-8', 'Sana Javed', 'Fiverr Level 2 Seller', 'Social Media Marketing with AI', 'social-media-marketing-with-ai', 'Faisalabad', '/images/generated/students/student-08.webp', 5, 'My English was the thing holding me back, not my skill. The mock client calls and the message templates changed everything about how I sell.', 'Sana had a design skill but had failed to convert a single Fiverr enquiry in six months. The positioning module narrowed her from \"graphic designer\" to \"Amazon listing image designer\", and the communication drills fixed her reply quality. She reached Level 2 within seven months.', 'Fiverr Level 2, $1,100/month', 1, 7),
  ('ts-9', 'Ahmed Kamal', 'E-Commerce Store Owner', 'TikTok Shop', 'tiktok-shop', 'Chiniot', '/images/generated/students/student-09.webp', 4, 'Honest teaching. They told me most stores fail and explained exactly why. Mine did not, because I followed the testing framework instead of guessing.', NULL, 'Profitable store in month 3', 0, 8),
  ('ts-10', 'Maryam Iqbal', 'Office Executive', 'Facebook Automation & Monetization', 'facebook-automation-and-monetization', 'Faisalabad', '/images/generated/students/student-10.webp', 5, 'I built the department\'s reporting dashboard in my second week back at work. My manager asked who taught me. I got the promotion two months later.', NULL, 'Promoted to Operations Officer', 0, 9),
  ('ts-11', 'Hamza Sheikh', 'Python Developer', 'Full Stack Development with AI', 'full-stack-development-with-ai', 'Faisalabad', '/images/generated/students/student-11.webp', 5, 'I automated a task that took our accounts team two days every month. That single script is why I was moved into the tech team.', NULL, 'Moved into a developer role', 0, 10),
  ('ts-12', 'Nimra Batool', 'Social Media Manager', 'Graphic Designing', 'graphic-designing', 'Faisalabad', '/images/generated/students/student-12.webp', 5, 'Four weeks, and I now produce a full month of content for three clients in a single day using the template system.', NULL, 'Rs 70,000/month part-time', 0, 11)
