-- faqs (19 rows)
INSERT INTO `faqs` (`id`, `question`, `answer`, `category`, `show_on_homepage`, `sort_order`) VALUES
  ('faq-what-exactly-is-included-in-the-14-august-azadi-sale', 'What exactly is included in the 14 August Azadi Sale?', 'A flat 50% discount on the full fee of every course we offer — all 14 programmes, all batch timings, on-campus and online. There is no minimum, no restricted list and no hidden registration charge. The discounted fee shown on each course page is the total amount you pay.', 'Azadi Sale', 1, 0),
  ('faq-when-does-the-azadi-sale-end', 'When does the Azadi Sale end?', 'The offer closes at 11:59 PM on 14 August. Enrolments confirmed before that deadline keep the discounted rate even if your batch starts in September. After the deadline, standard fees apply.', 'Azadi Sale', 1, 1),
  ('faq-can-i-reserve-my-seat-now-and-start-a-later-batch', 'Can I reserve my seat now and start a later batch?', 'Yes. Pay or confirm your enrolment before 14 August and you lock the 50% rate. You can then join any batch starting within the next three months, which is what most working students do.', 'Azadi Sale', 0, 2),
  ('faq-can-the-discount-be-combined-with-an-instalment-plan', 'Can the discount be combined with an instalment plan?', 'Yes. Courses of three months or longer can be paid in two or three instalments, and the 50% discount applies to the total before it is split. Speak to admissions and we will structure it around your situation.', 'Azadi Sale', 0, 3),
  ('faq-what-are-the-admission-requirements', 'What are the admission requirements?', 'Matric or equivalent, basic computer familiarity, and a genuine commitment to the weekly workload. There is no entry test for most courses. For the advanced development and AI tracks we have a short counselling call to make sure the course is the right fit for your goals.', 'Admissions', 0, 4),
  ('faq-how-do-i-enrol', 'How do I enrol?', 'Three ways: fill the enrolment form on any course page, message us on WhatsApp, or visit the campus on Jaranwala Road between 9 AM and 9 PM Monday to Saturday. Admissions will confirm your batch, timing and fee within one working day.', 'Admissions', 0, 5),
  ('faq-do-you-offer-scholarships-or-fee-concessions', 'Do you offer scholarships or fee concessions?', 'Yes. We reserve need-based seats each batch for students who cannot afford the fee, and offer additional concessions for siblings, groups of three or more, and for students with strong academic records. Ask admissions for the scholarship form.', 'Admissions', 1, 6),
  ('faq-are-classes-online-or-on-campus', 'Are classes online or on campus?', 'Both. Most courses run on-campus in Faisalabad, live online, or hybrid — you choose at enrolment and can switch if your circumstances change. Live online classes are interactive sessions with the same trainer, not pre-recorded videos.', 'Learning', 1, 7),
  ('faq-what-if-i-miss-a-class', 'What if I miss a class?', 'Every session is recorded and available in your student portal for the duration of the course plus three months. Trainers also run a weekly doubt-clearing session specifically for catching up.', 'Learning', 0, 8),
  ('faq-what-are-the-batch-timings', 'What are the batch timings?', 'Morning batches run 9 AM to 12 PM, evening batches 6 PM to 9 PM, and weekend batches on Saturday and Sunday. Most courses meet three days a week. Exact timings for your course are confirmed at enrolment.', 'Learning', 0, 9),
  ('faq-how-large-are-the-batches', 'How large are the batches?', 'Capped at 18 students. This is deliberate — beyond that number a trainer cannot review everyone\'s work weekly, which is the mechanism that makes the course work.', 'Learning', 0, 10),
  ('faq-do-i-need-my-own-laptop', 'Do I need my own laptop?', 'It helps enormously, but it is not a barrier. Our on-campus lab is available free of charge to enrolled students throughout their course, including outside class hours.', 'Learning', 0, 11),
  ('faq-is-the-certificate-recognised', 'Is the certificate recognised?', 'Our certificates are recognised by local employers and carry a unique verification code that anyone can check on our website. They also produce a LinkedIn-ready credential link. For internationally standardised vendor certification, our trainers guide you toward the relevant exam path.', 'Certification & Career', 1, 12),
  ('faq-do-you-guarantee-a-job', 'Do you guarantee a job?', 'No, and you should be cautious of any institute that does. What we guarantee is the support: CV clinics, mock interviews, portfolio reviews, freelance profile setup and direct introductions to our 45+ hiring partners. 76% of our graduates are earning within six months.', 'Certification & Career', 1, 13),
  ('faq-how-does-the-internship-work', 'How does the internship work?', 'Students who complete their course with strong project work are eligible for a supervised internship on live client projects, typically six to eight weeks. Several internships convert into full-time offers or ongoing freelance retainers each batch.', 'Certification & Career', 0, 14),
  ('faq-which-course-should-i-choose-for-freelancing', 'Which course should I choose for freelancing?', 'Pick a delivery skill plus Freelancing Mastery. The most successful combinations we see are Graphic Designing, Video Editing, Web Development or Digital Marketing paired with the freelancing track. Book a free counselling session and we will match a course to your background honestly.', 'Certification & Career', 0, 15),
  ('faq-how-do-i-pay-the-fee', 'How do I pay the fee?', 'Bank transfer, Easypaisa, JazzCash, or cash at the campus. You receive a formal receipt for every payment. International students can pay by card on request.', 'Fees & Payment', 0, 16),
  ('faq-is-there-a-refund-policy', 'Is there a refund policy?', 'Yes. If you attend the first two sessions and decide the course is not right for you, you receive a full refund minus any registration processing. Full details are in our Terms & Conditions.', 'Fees & Payment', 0, 17),
  ('faq-are-there-any-hidden-charges', 'Are there any hidden charges?', 'No. The fee shown covers tuition, course materials, lab access, tool accounts provided during the course, certification and career support. The only optional extra is a printed hard-copy certificate.', 'Fees & Payment', 0, 18)
ON DUPLICATE KEY UPDATE
  `question` = VALUES(`question`),
  `answer` = VALUES(`answer`),
  `category` = VALUES(`category`),
  `show_on_homepage` = VALUES(`show_on_homepage`),
  `sort_order` = VALUES(`sort_order`);

