-- benefits (8 rows)
INSERT INTO `benefits` (`id`, `title`, `description`, `icon`, `sort_order`) VALUES
  ('benefit-learn-by-building-not-watching', 'Learn by Building, Not Watching', 'Every module ends with something you have actually made. Our students graduate with portfolios, deployed URLs and live campaign data — not lecture notes.', 'Hammer', 0),
  ('benefit-instructors-who-still-do-the-work', 'Instructors Who Still Do the Work', 'Each trainer runs live client projects alongside teaching. The syllabus changes when the industry changes, because they feel it first.', 'UserCheck', 1),
  ('benefit-internship-included', 'Internship Included', 'Top performers move into a supervised internship on real client work. It is where classroom skill turns into professional judgement.', 'Briefcase', 2),
  ('benefit-job-and-freelance-assistance', 'Job & Freelance Assistance', 'CV clinics, mock interviews, portfolio reviews and direct introductions to our 45+ hiring partners. Plus profile setup on Fiverr and Upwork.', 'Handshake', 3),
  ('benefit-small-batches-real-attention', 'Small Batches, Real Attention', 'Maximum 18 students per batch. Your trainer knows your name, sees your work weekly, and notices when you fall behind.', 'Users', 4),
  ('benefit-verified-shareable-certificate', 'Verified, Shareable Certificate', 'Course completion certificates carry a unique verification code and a LinkedIn-ready credential link that employers can check instantly.', 'BadgeCheck', 5),
  ('benefit-flexible-timings', 'Flexible Timings', 'Morning, evening and weekend batches. Students, working professionals and business owners all study without giving up their day.', 'Clock', 6),
  ('benefit-lifetime-community-access', 'Lifetime Community Access', 'Graduates keep access to the alumni group where job openings, client leads and technical help circulate every single day.', 'MessagesSquare', 7)
ON DUPLICATE KEY UPDATE
  `title` = VALUES(`title`),
  `description` = VALUES(`description`),
  `icon` = VALUES(`icon`),
  `sort_order` = VALUES(`sort_order`);

-- differentiators (6 rows)
INSERT INTO `differentiators` (`id`, `title`, `body`, `proof`, `sort_order`) VALUES
  ('diff-practical-over-theoretical', 'Practical over theoretical', 'Roughly 80% of contact hours are hands-on. Theory is limited to what you need before touching the tool, and every session ends with an output you can show someone.', '80% hands-on', 0),
  ('diff-live-budgets-and-real-accounts', 'Live budgets and real accounts', 'Marketing students run campaigns with institute-funded ad spend. Amazon students work inside live Seller Central accounts. Development students deploy to production.', 'Real spend, real accounts', 1),
  ('diff-accountability-that-actually-works', 'Accountability that actually works', 'Weekly submissions, weekly critique, and a trainer who follows up when you miss two in a row. This is why our completion rate is 92% rather than the industry norm.', '92% completion', 2),
  ('diff-career-support-that-goes-past-the-certificate', 'Career support that goes past the certificate', 'CV clinics, mock interviews, portfolio reviews, employer introductions and freelance profile setup. Career services do not end on your last day of class.', '45+ hiring partners', 3),
  ('diff-honest-about-outcomes', 'Honest about outcomes', 'We publish our real numbers and we tell you when a course is not right for you. No guaranteed-income promises, because nobody can honestly make them.', 'Published outcomes', 4),
  ('diff-built-for-faisalabad', 'Built for Faisalabad', 'Fee structures, batch timings and course selection are designed around this city — its students, its businesses, its textile and export economy, and its internet.', 'Local since 2019', 5)
ON DUPLICATE KEY UPDATE
  `title` = VALUES(`title`),
  `body` = VALUES(`body`),
  `proof` = VALUES(`proof`),
  `sort_order` = VALUES(`sort_order`);

