-- milestones (8 rows)
INSERT INTO `milestones` (`id`, `year`, `title`, `body`, `sort_order`) VALUES
  ('milestone-2019', '2019', 'Globify opens its doors', 'Started with a single classroom on Jaranwala Road, two trainers and eleven students in the first web development batch.', 0),
  ('milestone-2020', '2020', 'Live online batches launch', 'Built a full remote delivery system during the pandemic, opening enrolment to students across Punjab and beyond.', 1),
  ('milestone-2021', '2021', 'Freelancing programme added', 'After tracking graduate outcomes we found the gap was selling, not skill. The Freelancing Mastery track was built to close it.', 2),
  ('milestone-2022', '2022', 'Internship programme begins', 'Partnered with local agencies and export businesses to place top performers into supervised, paid internships.', 3),
  ('milestone-2023', '2023', '5,000 students trained', 'Crossed five thousand graduates and expanded to a second floor with dedicated design and video editing labs.', 4),
